# ============================================================
# PHASE 6 - Cell 1: Regenerate missing per-sample predictions
# (Step 13's 9 MRSCN configs + Step 16's BiLSTM)
#
# These never had per-sample predictions saved - train_one_run() and
# train_classical_baseline() only ever wrote aggregate JSON/CSV metrics.
# Since real checkpoints exist for all 11 of these (confirmed by Cell 0),
# predictions are regenerated by loading each run's actual best_model.pt,
# rebuilding that run's StandardScaler deterministically (the same approach
# validated by Step 19's sanity-check scenario, which reproduced the
# original F1 to within ~2e-5), running inference on the locked test split,
# and applying the run's LOCKED best_threshold (never re-tuned).
#
# Built-in sanity check: the regenerated F1 is compared against the
# original results.json's test F1 for every run. If any don't match within
# tolerance, this says so loudly rather than silently saving bad data.
#
# LogisticRegression/RandomForest/XGBoost are deliberately NOT covered here
# - they have no checkpoint (would need a refit) and their predictions
# aren't needed until Phase 7 item 27 (ROC/PR curves vs. the Table 7
# group), which is the first item that actually needs them. Item 22's
# McNemar comparisons only name BERT-CNN/BiLSTM/TCN-Attention, and item 23
# is ablations-only, so nothing in items 21-24 needs the classical models.
# ============================================================
import os, json, shutil
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
from torch.cuda.amp import autocast
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import f1_score
from torch.utils.data import Dataset, DataLoader
from google.colab import drive
drive.mount('/content/drive', force_remount=False)

ROOT = '/content/drive/MyDrive/MRSCN_Revision'
DEVICE = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
AMP_ENABLED = True
BATCH_SIZE = 64
print(f"[INFO] Device: {DEVICE}")

# ------------------------------------------------------------
# Load TB caches locally (mirrors Step 13 Cell 3's local-copy pattern)
# ------------------------------------------------------------
CACHE_DIR = f'{ROOT}/cache'
LOCAL_CACHE = '/content/local_cache/TB'
os.makedirs(LOCAL_CACHE, exist_ok=True)
for fname in ['structured_features.npy', 'char_ids.npy', 'bert_embeddings.npy', 'structured_features_meta.json']:
    src = f'{CACHE_DIR}/TB/{fname}'
    dst = f'{LOCAL_CACHE}/{fname}'
    if not os.path.exists(dst) or os.path.getsize(dst) != os.path.getsize(src):
        print(f"[COPY] {fname} -> local disk ...")
        shutil.copyfile(src, dst)

struct_full = np.load(f'{LOCAL_CACHE}/structured_features.npy')          # (N,25)
char_full   = np.load(f'{LOCAL_CACHE}/char_ids.npy')                     # (N,200)
bert_mm     = np.load(f'{LOCAL_CACHE}/bert_embeddings.npy', mmap_mode='r')  # (N,768)

with open(f'{LOCAL_CACHE}/structured_features_meta.json') as f:
    struct_meta = json.load(f)
FEATURE_ORDER = struct_meta['feature_order'] if 'feature_order' in struct_meta else struct_meta['FEATURE_ORDER']
EXCLUDE = {'domain_age', 'ip_blacklisted', 'web_traffic', 'SFH'}
STATIC_FEATURE_INDICES = [i for i, name in enumerate(FEATURE_ORDER) if name not in EXCLUDE]
assert len(STATIC_FEATURE_INDICES) == 21

df = pd.read_csv(f'{ROOT}/data/processed/TB/step2_deduplicated_dataset.csv')
binary_label = df['binary_label'].values.astype(np.int64)

RUN_SPLITS = {}
for run_id in range(1, 6):
    with open(f'{ROOT}/splits/TB/run_{run_id}_indices.json') as f:
        RUN_SPLITS[str(run_id)] = json.load(f)

print(f"[OK] Loaded TB caches: struct={struct_full.shape}, char={char_full.shape}, bert={bert_mm.shape}")

# ------------------------------------------------------------
# Model classes (verbatim from Step 13 Cell 3/4 and Step 16 Cell 17)
# ------------------------------------------------------------
BERT_HIDDEN_SIZE = 768
CHAR_VOCAB = list("abcdefghijklmnopqrstuvwxyz0123456789-._:/?=&%")
MAX_CHAR_LEN = 200

class StructuralConsistencyModule(nn.Module):
    def __init__(self, bert_dim, char_dim, struct_dim):
        super().__init__()
        self.proj_bert   = nn.Linear(bert_dim,   128)
        self.proj_char   = nn.Linear(char_dim,   128)
        self.proj_struct = nn.Linear(struct_dim, 128)
    def forward(self, bert_feat, char_feat, struct_feat):
        b = self.proj_bert(bert_feat); c = self.proj_char(char_feat); s = self.proj_struct(struct_feat)
        bc = torch.cosine_similarity(b, c, dim=1)
        bs = torch.cosine_similarity(b, s, dim=1)
        cs = torch.cosine_similarity(c, s, dim=1)
        return torch.stack([bc, bs, cs], dim=1)

class ConfigurableMRSCN(nn.Module):
    def __init__(self, structured_dim=25, num_classes=2,
                 use_bert=True, use_char=True, use_struct=True, use_scm=True):
        super().__init__()
        assert use_bert or use_char or use_struct
        self.use_bert, self.use_char, self.use_struct = use_bert, use_char, use_struct
        self.use_scm = use_scm and use_bert and use_char and use_struct
        fusion_dim = 0
        if use_bert:
            self.bert_proj = nn.Sequential(nn.Linear(BERT_HIDDEN_SIZE, BERT_HIDDEN_SIZE),
                                            nn.LayerNorm(BERT_HIDDEN_SIZE), nn.Dropout(0.2))
            fusion_dim += BERT_HIDDEN_SIZE
        if use_char:
            self.char_embedding = nn.Embedding(len(CHAR_VOCAB) + 1, 32, padding_idx=0)
            self.char_cnn = nn.Sequential(
                nn.Conv1d(32, 64, kernel_size=3, padding=1), nn.ReLU(), nn.MaxPool1d(2),
                nn.Conv1d(64, 128, kernel_size=3, padding=1), nn.ReLU(), nn.MaxPool1d(2))
            self.char_fc = nn.Linear(128 * (MAX_CHAR_LEN // 4), 128)
            fusion_dim += 128
        if use_struct:
            self.struct_fc = nn.Sequential(nn.Linear(structured_dim, 64), nn.ReLU(),
                                            nn.Dropout(0.2), nn.Linear(64, 32))
            fusion_dim += 32
        if self.use_scm:
            self.consistency_module = StructuralConsistencyModule(bert_dim=BERT_HIDDEN_SIZE, char_dim=128, struct_dim=32)
            fusion_dim += 3
        self.classifier = nn.Sequential(
            nn.Linear(fusion_dim, 256), nn.ReLU(), nn.Dropout(0.3),
            nn.Linear(256, 64), nn.ReLU(), nn.Dropout(0.2),
            nn.Linear(64, num_classes))
    def forward(self, bert_features=None, char_ids=None, features=None):
        parts = []
        bert_feat = char_feat = struct_feat = None
        if self.use_bert:
            bert_feat = self.bert_proj(bert_features); parts.append(bert_feat)
        if self.use_char:
            x = self.char_embedding(char_ids).permute(0, 2, 1)
            x = self.char_cnn(x); x = x.flatten(start_dim=1)
            char_feat = self.char_fc(x); parts.append(char_feat)
        if self.use_struct:
            struct_feat = self.struct_fc(features); parts.append(struct_feat)
        if self.use_scm:
            parts.append(self.consistency_module(bert_feat, char_feat, struct_feat))
        combined = torch.cat(parts, dim=1)
        return self.classifier(combined)

class MRSCNDataset(Dataset):
    def __init__(self, indices, bert_src, char_src, struct_src, labels, use_bert, use_char, use_struct):
        self.indices = np.asarray(indices)
        self.bert_src, self.char_src, self.struct_src = bert_src, char_src, struct_src
        self.labels = labels
        self.use_bert, self.use_char, self.use_struct = use_bert, use_char, use_struct
    def __len__(self):
        return len(self.indices)
    def __getitem__(self, i):
        idx = self.indices[i]
        item = {"label": torch.tensor(self.labels[idx], dtype=torch.long)}
        if self.use_bert:
            item["bert_features"] = torch.tensor(np.asarray(self.bert_src[idx]), dtype=torch.float32)
        if self.use_char:
            item["char_ids"] = torch.tensor(self.char_src[idx].astype(np.int64), dtype=torch.long)
        if self.use_struct:
            item["features"] = torch.tensor(self.struct_src[idx], dtype=torch.float32)
        return item

class BiLSTMBaseline(nn.Module):
    def __init__(self, vocab_size, embed_dim=32, hidden_dim=128, num_layers=2, num_classes=2, dropout=0.3):
        super().__init__()
        self.embedding = nn.Embedding(vocab_size, embed_dim, padding_idx=0)
        self.lstm = nn.LSTM(embed_dim, hidden_dim, num_layers=num_layers, batch_first=True,
                             bidirectional=True, dropout=dropout if num_layers > 1 else 0.0)
        self.classifier = nn.Sequential(
            nn.Linear(hidden_dim * 2, 128), nn.ReLU(), nn.Dropout(dropout),
            nn.Linear(128, 32), nn.ReLU(), nn.Dropout(dropout * 0.67),
            nn.Linear(32, num_classes))
    def forward(self, char_ids):
        x = self.embedding(char_ids)
        _, (h_n, _) = self.lstm(x)
        feat = torch.cat([h_n[-2], h_n[-1]], dim=1)
        return self.classifier(feat)

class BiLSTMDataset(Dataset):
    def __init__(self, indices, char_src, labels):
        self.indices = np.asarray(indices)
        self.char_src = char_src
        self.labels = labels
    def __len__(self):
        return len(self.indices)
    def __getitem__(self, i):
        idx = self.indices[i]
        return {
            "char_ids": torch.tensor(self.char_src[idx].astype(np.int64), dtype=torch.long),
            "label": torch.tensor(self.labels[idx], dtype=torch.long),
        }

# ------------------------------------------------------------
# Configs (verbatim from Step 13 Cell 4)
# ------------------------------------------------------------
CONFIGS = [
    {'key': 'C1_full_mrscn',          'use_bert': True,  'use_char': True,  'use_struct': True, 'use_scm': True,  'structured_dim': 25, 'feature_indices': None},
    {'key': 'C2_no_scm',              'use_bert': True,  'use_char': True,  'use_struct': True, 'use_scm': False, 'structured_dim': 25, 'feature_indices': None},
    {'key': 'C3_no_threshold_tuning', 'use_bert': True,  'use_char': True,  'use_struct': True, 'use_scm': True,  'structured_dim': 25, 'feature_indices': None},
    {'key': 'C4_no_class_balancing',  'use_bert': True,  'use_char': True,  'use_struct': True, 'use_scm': True,  'structured_dim': 25, 'feature_indices': None},
    {'key': 'C5_structured_only',     'use_bert': False, 'use_char': False, 'use_struct': True, 'use_scm': False, 'structured_dim': 25, 'feature_indices': None},
    {'key': 'C6_bert_char',           'use_bert': True,  'use_char': True,  'use_struct': False,'use_scm': False, 'structured_dim': 25, 'feature_indices': None},
    {'key': 'C7_bert_struct',         'use_bert': True,  'use_char': False, 'use_struct': True, 'use_scm': False, 'structured_dim': 25, 'feature_indices': None},
    {'key': 'C8_char_struct',         'use_bert': False, 'use_char': True,  'use_struct': True, 'use_scm': False, 'structured_dim': 25, 'feature_indices': None},
    {'key': 'C9_static_only_21feat',  'use_bert': False, 'use_char': False, 'use_struct': True, 'use_scm': False, 'structured_dim': 21, 'feature_indices': STATIC_FEATURE_INDICES},
]

def run_inference_mrscn(model, loader, use_bert, use_char, use_struct):
    model.eval()
    y_list, prob_list = [], []
    with torch.no_grad():
        for batch in loader:
            kwargs = {}
            if use_bert:   kwargs['bert_features'] = batch['bert_features'].to(DEVICE)
            if use_char:   kwargs['char_ids']      = batch['char_ids'].to(DEVICE)
            if use_struct: kwargs['features']      = batch['features'].to(DEVICE)
            with autocast(enabled=AMP_ENABLED):
                logits = model(**kwargs)
            probs = torch.softmax(logits.float(), dim=1)[:, 1]
            y_list.append(batch['label'].numpy())
            prob_list.append(probs.cpu().numpy())
    return np.concatenate(y_list), np.concatenate(prob_list)

def run_inference_bilstm(model, loader):
    model.eval()
    y_list, prob_list = [], []
    with torch.no_grad():
        for batch in loader:
            char_ids = batch['char_ids'].to(DEVICE)
            with autocast(enabled=AMP_ENABLED):
                logits = model(char_ids)
            probs = torch.softmax(logits.float(), dim=1)[:, 1]
            y_list.append(batch['label'].numpy())
            prob_list.append(probs.cpu().numpy())
    return np.concatenate(y_list), np.concatenate(prob_list)

def save_predictions_npz(step, config_key, run_id, test_idx, y_true, y_prob, y_pred):
    out_dir = f'{ROOT}/results/{step}/{config_key}'
    os.makedirs(out_dir, exist_ok=True)
    np.savez_compressed(f'{out_dir}/run_{run_id}_predictions.npz',
                         test_idx=test_idx, y_true=y_true, y_prob=y_prob, y_pred=y_pred)

mismatch_warnings = []

# ------------------------------------------------------------
# Regenerate predictions for all 9 Step 13 configs
# ------------------------------------------------------------
for cfg in CONFIGS:
    config_key = cfg['key']
    print(f"\n=== Regenerating predictions: {config_key} (step13) ===")
    for run_id in range(1, 6):
        ckpt_path = f'{ROOT}/checkpoints/step13/{config_key}/run_{run_id}_best_model.pt'
        result_path = f'{ROOT}/results/step13/{config_key}/run_{run_id}_results.json'
        with open(result_path) as f:
            original = json.load(f)
        locked_threshold = original['best_threshold']
        original_f1 = original['test_metrics']['f1']

        split = RUN_SPLITS[str(run_id)]
        train_idx = np.array(split['train_indices'])
        test_idx = np.array(split['test_indices'])

        feat_idx = cfg['feature_indices']
        struct_sel = struct_full[:, feat_idx] if feat_idx is not None else struct_full
        scaler = StandardScaler()
        scaler.fit(struct_sel[train_idx])
        struct_scaled = scaler.transform(struct_sel).astype(np.float32)

        test_ds = MRSCNDataset(test_idx, bert_mm, char_full, struct_scaled, binary_label,
                                cfg['use_bert'], cfg['use_char'], cfg['use_struct'])
        test_loader = DataLoader(test_ds, batch_size=BATCH_SIZE, shuffle=False, num_workers=2, pin_memory=True)

        model = ConfigurableMRSCN(structured_dim=cfg['structured_dim'], use_bert=cfg['use_bert'],
                                   use_char=cfg['use_char'], use_struct=cfg['use_struct'],
                                   use_scm=cfg['use_scm']).to(DEVICE)
        state = torch.load(ckpt_path, map_location=DEVICE, weights_only=False)
        model.load_state_dict(state)

        y_test, test_probs = run_inference_mrscn(model, test_loader, cfg['use_bert'], cfg['use_char'], cfg['use_struct'])
        y_pred = (test_probs >= locked_threshold).astype(int)
        regenerated_f1 = f1_score(y_test, y_pred, zero_division=0)

        match = abs(regenerated_f1 - original_f1) < 1e-3
        flag = "OK" if match else "MISMATCH"
        if not match:
            mismatch_warnings.append(f"{config_key} run {run_id}: original F1={original_f1:.4f}, regenerated F1={regenerated_f1:.4f}")

        save_predictions_npz('step13', config_key, run_id, test_idx, y_test, test_probs, y_pred)
        print(f"  run {run_id}: original F1={original_f1:.4f} | regenerated F1={regenerated_f1:.4f} [{flag}]")

        del model, state, test_loader, test_ds, struct_scaled
        torch.cuda.empty_cache()

# ------------------------------------------------------------
# Regenerate predictions for BiLSTM (Step 16)
# ------------------------------------------------------------
print(f"\n=== Regenerating predictions: BiLSTM (step16) ===")
for run_id in range(1, 6):
    ckpt_path = f'{ROOT}/checkpoints/step16/BiLSTM/run_{run_id}_best_model.pt'
    result_path = f'{ROOT}/results/step16/BiLSTM/run_{run_id}_results.json'
    with open(result_path) as f:
        original = json.load(f)
    locked_threshold = original['best_threshold']
    original_f1 = original['test_metrics']['f1']

    split = RUN_SPLITS[str(run_id)]
    test_idx = np.array(split['test_indices'])

    test_ds = BiLSTMDataset(test_idx, char_full, binary_label)
    test_loader = DataLoader(test_ds, batch_size=BATCH_SIZE, shuffle=False, num_workers=2, pin_memory=True)

    model = BiLSTMBaseline(vocab_size=len(CHAR_VOCAB) + 1).to(DEVICE)
    state = torch.load(ckpt_path, map_location=DEVICE, weights_only=False)
    model.load_state_dict(state)

    y_test, test_probs = run_inference_bilstm(model, test_loader)
    y_pred = (test_probs >= locked_threshold).astype(int)
    regenerated_f1 = f1_score(y_test, y_pred, zero_division=0)

    match = abs(regenerated_f1 - original_f1) < 1e-3
    flag = "OK" if match else "MISMATCH"
    if not match:
        mismatch_warnings.append(f"BiLSTM run {run_id}: original F1={original_f1:.4f}, regenerated F1={regenerated_f1:.4f}")

    save_predictions_npz('step16', 'BiLSTM', run_id, test_idx, y_test, test_probs, y_pred)
    print(f"  run {run_id}: original F1={original_f1:.4f} | regenerated F1={regenerated_f1:.4f} [{flag}]")

    del model, state, test_loader, test_ds
    torch.cuda.empty_cache()

print("\n" + "=" * 80)
if mismatch_warnings:
    print(f"[WARNING] {len(mismatch_warnings)} run(s) did NOT reproduce the original F1 within tolerance:")
    for w in mismatch_warnings:
        print(f"  - {w}")
    print("Investigate before trusting these regenerated predictions.")
else:
    print("[OK] All 55 regenerated F1 scores (11 configs x 5 runs) match the original locked "
          "results.json within 1e-3. Predictions are trustworthy.")
print("=" * 80)
